/**
 * @fileoverview Test the usage of a deprecated config
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-config-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0',
            toVersion: '7.9.0'
        }
    }
});
ruleTester.run('no-deprecated-config-usage', rule, {

    valid: [
        {
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    quickTips: true
                });
            `
        }
    ],

    invalid: [
        {
            code: `
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    associations: []
                });
            `,
            errors: [{
                message: /Usage of deprecated config 'associations'.*/
            }]
        },
        {
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                    enterAnimation: true,
                    exitAnimation: function () {}
                });

                Ext.create({
                    xclass: 'Ext.Button',
                    enterAnimation: true,
                    exitAnimation: function () {}
                });

                var className = 'Ext.carousel.Carousel'
                Ext.create({
                    xclass: className,
                    enterAnimation: true,
                    exitAnimation: function () {}
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                    showAnimation: true,
                    hideAnimation: function () {}
                });

                Ext.create({
                    xclass: 'Ext.Button',
                    showAnimation: true,
                    hideAnimation: function () {}
                });

                var className = 'Ext.carousel.Carousel'
                Ext.create({
                    xclass: className,
                    showAnimation: true,
                    hideAnimation: function () {}
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'enterAnimation' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'exitAnimation' found for 'Ext.Component'.*/ },
                { message: /Usage of deprecated config 'enterAnimation' found for 'Ext.Button'.*/ },
                { message: /Usage of deprecated config 'exitAnimation' found for 'Ext.Button'.*/ },
                { message: /Usage of deprecated config 'enterAnimation' found for 'Ext.carousel.Carousel'.*/ },
                { message: /Usage of deprecated config 'exitAnimation' found for 'Ext.carousel.Carousel'.*/ }
            ]
        },
        {
            code: `
                Ext.define('MyCustomDataView', {
                    extend: 'Ext.dataview.DataView',
                    enableTextSelection: true
                });
            `,
            output: `
                Ext.define('MyCustomDataView', {
                    extend: 'Ext.dataview.DataView',
                    userSelectable: true
                });
            `,
            errors: [
                { message: /Usage of deprecated config 'enableTextSelection' found for 'Ext.dataview.DataView'.*/ }
            ]
        }
    ]
});
